// Characterization tests: pin CURRENT behaviour of order totals, quirks included.
import { test, before, after } from 'node:test'
import assert from 'node:assert/strict'
import { createServer } from 'node:http'
import { createApp } from '../src/app.mjs'

const prices = { A: 10, B: 25, C: 10.99, D: 33.35, E: 0.1, F: 1000 }
const pricing = { priceOf: async (sku) => prices[sku] }
let server, base

before(async () => {
  server = createServer(createApp({ pricing }))
  await new Promise((r) => server.listen(0, r))
  base = `http://localhost:${server.address().port}`
})
after(() => server.close())

const post = async (items) => {
  const res = await fetch(`${base}/orders`, { method: 'POST', body: JSON.stringify({ items }) })
  return { status: res.status, body: await res.json() }
}

const cases = [
  ['single item, no discount', [{ sku: 'A', qty: 1 }], 10],
  ['multiple lines are summed', [{ sku: 'A', qty: 2 }, { sku: 'B', qty: 2 }], 70],
  ['exactly 100 gets no discount (threshold is strictly > 100)', [{ sku: 'A', qty: 10 }], 100],
  ['just over 100 gets 10% off', [{ sku: 'A', qty: 11 }], 99],
  ['larger order: 10% off', [{ sku: 'B', qty: 10 }], 225],
  ['very large order: still a flat 10%, no tiers', [{ sku: 'F', qty: 100 }], 90000],
  ['total is floored, not rounded (cents dropped)', [{ sku: 'C', qty: 3 }], 32],
  ['floored after discount: 109.9 -> 98.91 -> 98', [{ sku: 'C', qty: 10 }], 98],
  ['floating point: 33.35*3=100.05 -> 90.045 -> 90', [{ sku: 'D', qty: 3 }], 90],
  ['fractional total below threshold is floored', [{ sku: 'E', qty: 7 }], 0],
  ['qty 0 contributes nothing', [{ sku: 'A', qty: 0 }], 0],
  ['negative qty reduces total (no validation)', [{ sku: 'A', qty: 5 }, { sku: 'B', qty: -1 }], 25],
  ['discount applies to the sum across lines, not per line', [{ sku: 'B', qty: 3 }, { sku: 'A', qty: 3 }], 94],
]

for (const [name, items, total] of cases) {
  test(name, async () => {
    const { status, body } = await post(items)
    assert.equal(status, 201)
    assert.equal(body.total, total)
  })
}

test('unknown sku (undefined price) yields null total', async () => {
  const { status, body } = await post([{ sku: 'ZZZ', qty: 1 }])
  assert.equal(status, 201)
  assert.equal(body.total, null)
})

test('created order is retrievable with same total and sequential string ids', async () => {
  const { body } = await post([{ sku: 'B', qty: 10 }])
  const got = await (await fetch(`${base}/orders/${body.id}`)).json()
  assert.deepEqual(got, body)
  assert.equal(typeof body.id, 'string')
})

test('validation: empty/missing items -> 400', async () => {
  for (const items of [[], undefined]) {
    const res = await fetch(`${base}/orders`, { method: 'POST', body: JSON.stringify({ items }) })
    assert.equal(res.status, 400)
    assert.deepEqual(await res.json(), { error: 'items required' })
  }
  const bad = await fetch(`${base}/orders`, { method: 'POST', body: '{nope' })
  assert.equal(bad.status, 400)
})

test('unknown order id returns 200 with error body (bug pinned)', async () => {
  const res = await fetch(`${base}/orders/does-not-exist`)
  assert.equal(res.status, 200)
  assert.deepEqual(await res.json(), { error: 'not found' })
})

test('unknown route -> 404', async () => {
  const res = await fetch(`${base}/nope`)
  assert.equal(res.status, 404)
})
EOF
